@Composable
fun QuickGuideOverlay(
    state: AppUiState,
    onSelect: (Channel) -> Unit,
    onFavorite: (Channel) -> Unit,
    onClose: () -> Unit
) {
    var section by remember { mutableStateOf("Recentes") }
    val requester = remember { FocusRequester() }

    val channels = when (section) {
        "Favoritos" -> state.channels.filter { it.id in state.favorites }
        "Recentes" -> quickByIds(state.channels, state.recentChannelIds)
        "Brasil" -> state.channels.filter(ChannelClassifier::isBrazil)
        "Esportes" -> state.channels.filter { ChannelClassifier.category(it) == "Esportes" }
        "Notícias" -> state.channels.filter { ChannelClassifier.category(it) == "Notícias" }
        else -> state.channels
    }.take(100)

    LaunchedEffect(section, channels.firstOrNull()?.id) {
        if (channels.isNotEmpty()) {
            delay(100)
            runCatching { requester.requestFocus() }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .fillMaxHeight(0.55f)
            .background(Color(0xF205080C))
            .padding(horizontal = 30.dp, vertical = 17.dp)
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(
                "CANAIS",
                color = SanchesColors.PrimaryText,
                fontSize = 20.sp,
                fontWeight = FontWeight.Black
            )

            Spacer(Modifier.width(14.dp))

            listOf("Recentes", "Favoritos", "Brasil", "Esportes", "Notícias", "Todos").forEach { item ->
                QuickChip(
                    label = item,
                    selected = section == item,
                    onClick = { section = item }
                )
                Spacer(Modifier.width(6.dp))
            }

            Spacer(Modifier.weight(1f))

            Text(
                "BACK fecha",
                color = SanchesColors.Muted,
                fontSize = 11.sp,
                modifier = Modifier.clickable(onClick = onClose)
            )
        }

        Spacer(Modifier.height(11.dp))

        if (channels.isEmpty()) {
            Text(
                "Ainda não há canais nesta seção.",
                color = SanchesColors.SecondaryText,
                fontSize = 14.sp,
                modifier = Modifier.padding(20.dp)
            )
        } else {
            LazyColumn(verticalArrangement = Arrangement.spacedBy(5.dp)) {
                items(channels, key = { it.id }) { channel ->
                    QuickRow(
                        channel = channel,
                        program = state.programs[channel.id],
                        favorite = channel.id in state.favorites,
                        focusFirst = channel.id == channels.first().id,
                        requester = requester,
                        onSelect = { onSelect(channel) },
                        onFavorite = { onFavorite(channel) }
                    )
                }
            }
        }
    }
}

@Composable
private fun QuickChip(
    label: String,
    selected: Boolean,
    onClick: () -> Unit
) {
    var focused by remember { mutableStateOf(false) }

    androidx.compose.foundation.layout.Box(
        modifier = Modifier
            .height(34.dp)
            .clip(RoundedCornerShape(10.dp))
            .background(
                when {
                    focused -> SanchesColors.Focus
                    selected -> SanchesColors.AccentStrong
                    else -> SanchesColors.SurfaceStrong
                }
            )
            .onFocusChanged { focused = it.isFocused }
            .clickable(onClick = onClick)
            .focusable()
            .padding(horizontal = 10.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = if (focused) SanchesColors.FocusText else SanchesColors.PrimaryText,
            fontSize = 11.sp,
            fontWeight = FontWeight.Bold
        )
    }
}

@Composable
private fun QuickRow(
    channel: Channel,
    program: ProgramInfo?,
    favorite: Boolean,
    focusFirst: Boolean,
    requester: FocusRequester,
    onSelect: () -> Unit,
    onFavorite: () -> Unit
) {
    var focused by remember { mutableStateOf(false) }
    var rowModifier: Modifier = Modifier

    if (focusFirst) {
        rowModifier = rowModifier.focusRequester(requester)
    }

    Row(
        modifier = rowModifier
            .fillMaxWidth()
            .height(68.dp)
            .clip(RoundedCornerShape(13.dp))
            .background(if (focused) SanchesColors.Focus else Color(0xFF111820))
            .onFocusChanged { focused = it.isFocused }
            .clickable(onClick = onSelect)
            .focusable()
            .padding(horizontal = 11.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        SanchesChannelLogo(channel, Modifier.size(42.dp))
        Spacer(Modifier.width(10.dp))

        Text(
            channel.number,
            modifier = Modifier.width(52.dp),
            color = if (focused) SanchesColors.FocusText.copy(alpha = .62f) else SanchesColors.Accent,
            fontSize = 11.sp
        )

        Column(Modifier.weight(1f)) {
            Text(
                channel.name,
                color = if (focused) SanchesColors.FocusText else SanchesColors.PrimaryText,
                fontSize = 15.sp,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            Text(
                program?.title ?: ChannelClassifier.category(channel),
                color = if (focused) SanchesColors.FocusText.copy(alpha = .65f) else SanchesColors.SecondaryText,
                fontSize = 10.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            program?.nextTitle?.let { next ->
                Text(
                    "Depois: " + next,
                    color = if (focused) SanchesColors.FocusText.copy(alpha = .48f) else SanchesColors.Muted,
                    fontSize = 9.sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        }

        if (channel.playbackUris().size > 1) {
            Text(
                channel.playbackUris().size.toString() + "×",
                color = if (focused) SanchesColors.FocusText.copy(alpha = .6f) else SanchesColors.Muted,
                fontSize = 10.sp
            )
            Spacer(Modifier.width(8.dp))
        }

        Text(
            if (favorite) "★" else "☆",
            color = if (focused) SanchesColors.FocusText else SanchesColors.Accent,
            fontSize = 18.sp,
            modifier = Modifier
                .clickable(onClick = onFavorite)
                .padding(7.dp)
        )
    }
}

private fun quickByIds(
    channels: List<Channel>,
    ids: List<String>
): List<Channel> {
    val index = channels.associateBy { it.id }
    return ids.mapNotNull(index::get).distinctBy { it.id }
}

