@Composable
fun VodPlayerSurface(
    item: VodItem,
    onBack: () -> Unit
) {
    val context = LocalContext.current
    var captionsEnabled by remember(item.id) {
        mutableStateOf(item.subtitles.isNotEmpty())
    }
    var subtitleIndex by remember(item.id) { mutableStateOf(0) }
    var playbackStatus by remember(item.id) { mutableStateOf("Preparando…") }

    val player = remember(item.id) {
        ExoPlayer.Builder(context)
            .setRenderersFactory(
                DefaultRenderersFactory(context)
                    .setEnableDecoderFallback(true)
            )
            .build()
            .apply {
                playWhenReady = true
                setHandleAudioBecomingNoisy(true)
            }
    }

    BackHandler(onBack = onBack)

    LaunchedEffect(item.id, captionsEnabled, subtitleIndex) {
        val selected = item.subtitles.getOrNull(subtitleIndex)
        val textLanguages = buildList {
            selected?.language?.takeIf { it != "und" }?.let(::add)
            add("pt-BR")
            add("pt")
            add("en")
            add("es")
        }.distinct().toTypedArray()

        player.trackSelectionParameters = player.trackSelectionParameters
            .buildUpon()
            .setPreferredAudioLanguages("pt-BR", "pt", "en")
            .setPreferredTextLanguages(*textLanguages)
            .setTrackTypeDisabled(C.TRACK_TYPE_TEXT, !captionsEnabled)
            .build()
    }

    DisposableEffect(player, item.id) {
        val listener = object : Player.Listener {
            override fun onPlaybackStateChanged(playbackState: Int) {
                playbackStatus = when (playbackState) {
                    Player.STATE_BUFFERING -> "Carregando…"
                    Player.STATE_READY -> "Reproduzindo"
                    Player.STATE_ENDED -> "Fim"
                    else -> playbackStatus
                }
            }

            override fun onPlayerError(error: androidx.media3.common.PlaybackException) {
                playbackStatus = "Falha na reprodução"
            }
        }
        player.addListener(listener)

        val playback = item.playbackUrl
        if (!playback.isNullOrBlank()) {
            val subtitles = item.subtitles.map { subtitle ->
                MediaItem.SubtitleConfiguration.Builder(Uri.parse(subtitle.uri))
                    .setMimeType(subtitle.mimeType)
                    .setLanguage(subtitle.language)
                    .setLabel(subtitle.label)
                    .setSelectionFlags(
                        if (subtitle.isDefault) C.SELECTION_FLAG_DEFAULT else 0
                    )
                    .build()
            }

            val mediaItem = MediaItem.Builder()
                .setMediaId(item.id)
                .setUri(playback)
                .setSubtitleConfigurations(subtitles)
                .build()

            player.setMediaItem(mediaItem)
            player.prepare()
            player.play()
        } else {
            playbackStatus = "Filme sem arquivo reproduzível"
        }

        onDispose {
            player.removeListener(listener)
            player.release()
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black)
    ) {
        AndroidView(
            factory = {
                PlayerView(it).apply {
                    useController = true
                    controllerAutoShow = false
                    controllerShowTimeoutMs = 4_000
                    resizeMode = AspectRatioFrameLayout.RESIZE_MODE_FIT
                    setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING)
                    this.player = player
                    isFocusable = true
                    requestFocus()
                }
            },
            update = { it.player = player },
            modifier = Modifier.fillMaxSize()
        )

        Column(
            modifier = Modifier
                .align(Alignment.BottomStart)
                .fillMaxWidth()
                .background(
                    Brush.verticalGradient(
                        listOf(Color.Transparent, Color(0xF2070A0E))
                    )
                )
                .padding(horizontal = 34.dp, vertical = 24.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Text(
                item.title,
                color = Color.White,
                fontSize = 26.sp,
                fontWeight = FontWeight.Black
            )

            val metadata = buildList {
                item.year?.let(::add)
                item.catalog.takeIf(String::isNotBlank)?.let(::add)
                item.licenseName?.let(::add)
            }.joinToString(" • ")

            if (metadata.isNotBlank()) {
                Text(
                    metadata,
                    color = SanchesColors.SecondaryText,
                    fontSize = 12.sp
                )
            }

            Text(
                playbackStatus,
                color = SanchesColors.Muted,
                fontSize = 11.sp
            )

            Row(
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                val selectedSubtitle = item.subtitles.getOrNull(subtitleIndex)
                VodControlButton(
                    label = when {
                        !captionsEnabled -> "Legenda: desligada"
                        selectedSubtitle != null -> "Legenda: ${selectedSubtitle.label}"
                        else -> "Legenda: automática"
                    }
                ) {
                    if (item.subtitles.isEmpty()) {
                        captionsEnabled = !captionsEnabled
                    } else if (!captionsEnabled) {
                        subtitleIndex = 0
                        captionsEnabled = true
                    } else if (subtitleIndex < item.subtitles.lastIndex) {
                        subtitleIndex += 1
                    } else {
                        captionsEnabled = false
                        subtitleIndex = 0
                    }
                }

                Text(
                    if (item.subtitles.isEmpty()) {
                        "Faixas embutidas quando disponíveis"
                    } else {
                        "${item.subtitles.size} faixa(s) externa(s) • PT-BR priorizado"
                    },
                    color = SanchesColors.SecondaryText,
                    fontSize = 11.sp
                )

                Spacer(Modifier.weight(1f))

                VodControlButton(label = "Voltar") {
                    onBack()
                }
            }
        }
    }
}

@Composable
private fun VodControlButton(
    label: String,
    enabled: Boolean = true,
    onClick: () -> Unit
) {
    var focused by remember { mutableStateOf(false) }

    Box(
        modifier = Modifier
            .height(42.dp)
            .clip(RoundedCornerShape(18.dp))
            .background(
                when {
                    !enabled -> Color(0xFF20262C)
                    focused -> SanchesColors.Focus
                    else -> SanchesColors.AccentStrong
                }
            )
            .onFocusChanged { focused = it.isFocused }
            .then(
                if (enabled) {
                    Modifier.clickable(onClick = onClick).focusable()
                } else {
                    Modifier
                }
            )
            .padding(horizontal = 16.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = when {
                !enabled -> SanchesColors.Muted
                focused -> SanchesColors.FocusText
                else -> Color.White
            },
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold
        )
    }
}

