@Composable
private fun AppShell(controller: ZappController) {
    val state = controller.state

    Row(
        modifier = Modifier
            .fillMaxSize()
            .background(SanchesColors.Background)
    ) {
        NavRail(
            selected = state.screen,
            onNavigate = controller::open
        )

        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight()
                .background(
                    Brush.verticalGradient(
                        listOf(Color(0xFF0B151D), SanchesColors.Background)
                    )
                )
        ) {
            when (state.screen) {
                AppScreen.HOME -> HomeScreen(state, controller)
                AppScreen.LIVE -> ChannelNavigatorScreen(state, controller)
                AppScreen.MOVIES -> MoviesScreen(controller)
                AppScreen.SERIES -> CuratedScreen(
                    title = "Séries & Entretenimento",
                    subtitle = "Canais identificados como séries e entretenimento",
                    channels = state.channels.filter(::isSeriesChannel),
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
                AppScreen.SPORTS -> CuratedScreen(
                    title = "Esportes",
                    subtitle = "Canais e programação esportiva identificados no catálogo e no EPG",
                    channels = state.channels.filter { channel ->
                        isSportsChannel(channel, state.programs[channel.id])
                    },
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
                AppScreen.GUIDE -> GuideScreen(state, controller::select)
                AppScreen.FAVORITES -> CuratedScreen(
                    title = "Minha TV",
                    subtitle = "Seus canais favoritos",
                    channels = state.channels.filter { it.id in state.favorites },
                    programs = state.programs,
                    favorites = state.favorites,
                    onSelect = controller::select,
                    onFavorite = controller::toggleFavorite
                )
                AppScreen.SEARCH -> SearchScreen(state, controller::select)
                AppScreen.SOURCES -> SourcesScreen(state, controller)
                AppScreen.DIAGNOSTICS -> DiagnosticsScreen(controller)
                AppScreen.WATCH -> Unit
            }
        }
    }
}

