@Composable
private fun GuideScreen(
    state: AppUiState,
    onSelect: (Channel) -> Unit
) {
    val now = System.currentTimeMillis()
    var dayOffset by remember { mutableIntStateOf(0) }

    val dayStart = remember(dayOffset) {
        Calendar.getInstance().apply {
            timeInMillis = now
            set(Calendar.HOUR_OF_DAY, 0)
            set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
            add(Calendar.DAY_OF_YEAR, dayOffset)
        }.timeInMillis
    }
    val dayEnd = dayStart + 24L * 60L * 60L * 1000L
    val windowStart = if (dayOffset == 0) {
        now - (now % (30L * 60L * 1000L))
    } else {
        dayStart
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 28.dp, vertical = 24.dp)
    ) {
        SectionTitle(
            "Guia em grade",
            "${state.schedule.values.sumOf { it.size }} programas • EPG de até 7 dias"
        )
        Spacer(Modifier.height(10.dp))

        LazyRow(horizontalArrangement = Arrangement.spacedBy(7.dp)) {
            items(7) { offset ->
                val label = when (offset) {
                    0 -> "Hoje"
                    1 -> "Amanhã"
                    else -> SimpleDateFormat("EEE dd/MM", Locale("pt", "BR")).format(
                        Date(dayStart + (offset - dayOffset) * 24L * 60L * 60L * 1000L)
                    )
                }
                FilterChip(
                    label = label.replaceFirstChar { it.uppercase() },
                    selected = dayOffset == offset,
                    onClick = { dayOffset = offset }
                )
            }
        }

        Spacer(Modifier.height(10.dp))

        LazyRow(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
            val slots = (((dayEnd - windowStart).coerceAtLeast(0L)) / (30L * 60L * 1000L))
                .toInt()
                .coerceIn(1, 49)
            items(slots + 1) { step ->
                val time = windowStart + step * 30L * 60L * 1000L
                Box(
                    modifier = Modifier
                        .width(150.dp)
                        .height(34.dp)
                        .clip(RoundedCornerShape(10.dp))
                        .background(
                            if (dayOffset == 0 && step == 0) {
                                SanchesColors.AccentStrong
                            } else {
                                SanchesColors.SurfaceStrong
                            }
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        if (dayOffset == 0 && step == 0) {
                            "AGORA ${formatTime(now)}"
                        } else {
                            formatTime(time)
                        },
                        color = SanchesColors.PrimaryText,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }

        Spacer(Modifier.height(10.dp))

        LazyColumn(verticalArrangement = Arrangement.spacedBy(6.dp)) {
            items(state.channels, key = { it.id }) { channel ->
                val slots = state.schedule[channel.id]
                    .orEmpty()
                    .filter { it.endMillis > windowStart && it.startMillis < dayEnd }
                    .take(64)

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(86.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    var channelFocused by remember { mutableStateOf(false) }
                    Box(
                        modifier = Modifier
                            .width(190.dp)
                            .fillMaxHeight()
                            .clip(RoundedCornerShape(14.dp))
                            .background(
                                if (channelFocused) SanchesColors.Focus else SanchesColors.SurfaceStrong
                            )
                            .onFocusChanged { channelFocused = it.isFocused }
                            .clickable { onSelect(channel) }
                            .focusable()
                            .padding(horizontal = 12.dp),
                        contentAlignment = Alignment.CenterStart
                    ) {
                        Column {
                            Text(
                                channel.number,
                                color = if (channelFocused) SanchesColors.FocusText else SanchesColors.Accent,
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold
                            )
                            Text(
                                channel.name,
                                color = if (channelFocused) SanchesColors.FocusText else SanchesColors.PrimaryText,
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                maxLines = 2,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                    }

                    Spacer(Modifier.width(8.dp))

                    if (slots.isEmpty()) {
                        Text(
                            "Sem programação disponível para este dia",
                            color = SanchesColors.Muted,
                            fontSize = 12.sp
                        )
                    } else {
                        LazyRow(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                            items(
                                slots,
                                key = { slot -> "${channel.id}:${slot.startMillis}:${slot.title}" }
                            ) { slot ->
                                ProgramGridCard(
                                    slot = slot,
                                    now = now,
                                    onClick = { onSelect(channel) }
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun ProgramGridCard(
    slot: ProgramSlot,
    now: Long,
    onClick: () -> Unit
) {
    var focused by remember { mutableStateOf(false) }
    val durationMinutes = ((slot.endMillis - slot.startMillis) / 60_000L)
        .coerceIn(15L, 180L)
    val cardWidth = (durationMinutes / 30f * 150f).coerceIn(120f, 520f)

    Column(
        modifier = Modifier
            .width(cardWidth.dp)
            .fillMaxHeight()
            .clip(RoundedCornerShape(14.dp))
            .background(
                when {
                    focused -> SanchesColors.Focus
                    slot.isLive(now) -> SanchesColors.AccentStrong
                    else -> SanchesColors.Surface
                }
            )
            .onFocusChanged { focused = it.isFocused }
            .clickable(onClick = onClick)
            .focusable()
            .padding(horizontal = 12.dp, vertical = 9.dp),
        verticalArrangement = Arrangement.Center
    ) {
        Text(
            "${formatTime(slot.startMillis)} – ${formatTime(slot.endMillis)}",
            color = if (focused) SanchesColors.FocusText else SanchesColors.Accent,
            fontSize = 10.sp,
            fontWeight = FontWeight.Bold
        )
        Text(
            slot.title,
            color = if (focused) SanchesColors.FocusText else SanchesColors.PrimaryText,
            fontSize = 12.sp,
            fontWeight = FontWeight.SemiBold,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis
        )
    }
}

@Composable
private fun SearchScreen(
    state: AppUiState,
    onSelect: (Channel) -> Unit
) {
    var query by remember { mutableStateOf("") }
    val requester = remember { FocusRequester() }

    LaunchedEffect(Unit) {
        delay(100)
        runCatching { requester.requestFocus() }
    }

    val normalized = ChannelResolver.normalize(query)
    val filtered = if (normalized.isBlank()) {
        state.channels.take(80)
    } else {
        state.channels.filter { channel ->
            ChannelResolver.normalize(channel.name).contains(normalized) ||
                ChannelResolver.normalize(channel.number).contains(normalized) ||
                ChannelResolver.normalize(channel.category).contains(normalized) ||
                ChannelResolver.normalize(channel.sourceName).contains(normalized) ||
                ChannelResolver.normalize(state.programs[channel.id]?.title.orEmpty()).contains(normalized) ||
                ChannelResolver.normalize(state.programs[channel.id]?.nextTitle.orEmpty()).contains(normalized) ||
                state.schedule[channel.id].orEmpty().any { slot ->
                    ChannelResolver.normalize(slot.title).contains(normalized) ||
                        ChannelResolver.normalize(slot.subtitle.orEmpty()).contains(normalized)
                }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 32.dp, vertical = 26.dp)
    ) {
        SectionTitle("Buscar", "Canais, categorias e programação")
        Spacer(Modifier.height(14.dp))

        OutlinedTextField(
            value = query,
            onValueChange = { query = it },
            singleLine = true,
            label = { Text("O que você quer assistir?") },
            modifier = Modifier
                .fillMaxWidth(0.68f)
                .focusRequester(requester)
        )

        Spacer(Modifier.height(16.dp))

        LazyColumn(verticalArrangement = Arrangement.spacedBy(7.dp)) {
            items(filtered, key = { it.id }) { channel ->
                ChannelRow(
                    channel = channel,
                    program = state.programs[channel.id],
                    favorite = channel.id in state.favorites,
                    onClick = { onSelect(channel) },
                    onFavorite = {}
                )
            }
        }
    }
}

