private fun isMovieChannel(channel: Channel): Boolean {
    val value = ChannelResolver.normalize("\${channel.category} \${channel.name}")
    return listOf("MOVIE", "FILME", "CINEMA", "FILMS")
        .any { token -> value.contains(token) }
}

private fun isSeriesChannel(channel: Channel): Boolean {
    val value = ChannelResolver.normalize("\${channel.category} \${channel.name}")
    return listOf("SERIE", "SERIES", "ENTERTAINMENT", "ENTRETENIMENTO")
        .any { token -> value.contains(token) }
}

private fun isSportsChannel(channel: Channel, program: ProgramInfo?): Boolean {
    val value = ChannelResolver.normalize(
        listOf(
            channel.category,
            channel.name,
            program?.title.orEmpty(),
            program?.subtitle.orEmpty()
        ).joinToString(" ")
    )

    return listOf(
        "ESPORTE", "SPORT", "FUTEBOL", "SOCCER", "BASQUETE", "BASKET",
        "NBA", "NBB", "TENIS", "TENNIS", "VOLEI", "VOLLEY", "MMA", "UFC",
        "FORMULA", "MOTOGP", "NFL"
    ).any(value::contains)
}

private fun programTime(program: ProgramInfo?): String? {
    val start = program?.startMillis ?: return null
    val end = program.endMillis ?: return null
    return "\${formatTime(start)} – \${formatTime(end)}"
}

private fun nextProgramTime(program: ProgramInfo?): String? =
    program?.nextStartMillis?.let(::formatTime)

private fun formatTime(value: Long): String =
    SimpleDateFormat("HH:mm", Locale("pt", "BR")).format(Date(value))

private fun formatDateTime(value: Long): String =
    SimpleDateFormat("dd/MM HH:mm", Locale("pt", "BR")).format(Date(value))

package com.mukasanches.zapptv.vod

import java.text.Normalizer
import kotlin.math.abs

object CinemaRightsEngine {
    fun classify(
        source: String,
        licenseName: String?,
        licenseUrl: String?
    ): RightsStatus {
        val text = listOfNotNull(source, licenseName, licenseUrl)
            .joinToString(" ")
            .lowercase()

        return when {
            "public domain" in text ||
                "publicdomain" in text ||
                "no known copyright" in text ||
                "no known restrictions" in text -> RightsStatus.PUBLIC_DOMAIN

            "creativecommons.org/publicdomain" in text ||
                "cc0" in text -> RightsStatus.PUBLIC_DOMAIN

            "cc-by-sa" in text ||
                "cc by-sa" in text ||
                "by-sa" in text -> RightsStatus.ATTRIBUTION_REQUIRED

            "cc-by" in text ||
                "cc by" in text ||
                "creative commons attribution" in text -> RightsStatus.ATTRIBUTION_REQUIRED

            "creativecommons.org" in text ||
                "creative commons" in text -> RightsStatus.OPEN_LICENSE

            source.equals("Wikimedia Commons", ignoreCase = true) ->
                RightsStatus.OPEN_LICENSE

            source.startsWith("NASA", ignoreCase = true) ->
                RightsStatus.OPEN_LICENSE

            "all rights reserved" in text ||
                "restricted" in text -> RightsStatus.RESTRICTED

            else -> RightsStatus.UNKNOWN
        }
    }

    fun normalize(item: VodItem): VodItem {
        val status = if (item.rightsStatus == RightsStatus.UNKNOWN) {
            classify(item.source, item.licenseName, item.licenseUrl)
        } else {
            item.rightsStatus
        }
        return item.copy(
            rightsStatus = status,
            providers = (item.providers + item.source)
                .filter(String::isNotBlank)
                .distinct()
        )
    }

    fun canAutoPlay(item: VodItem): Boolean =
        item.rightsStatus in setOf(
            RightsStatus.PUBLIC_DOMAIN,
            RightsStatus.OPEN_LICENSE,
            RightsStatus.ATTRIBUTION_REQUIRED
        ) || item.source == "Wikimedia Commons" ||
            item.source.startsWith("NASA", ignoreCase = true)
}

object MovieIdentityResolver {
    fun merge(items: List<VodItem>): List<VodItem> {
        val result = mutableListOf<VodItem>()

        items.map(CinemaRightsEngine::normalize).forEach { incoming ->
            val matchIndex = result.indexOfFirst { existing ->
                sameMovie(existing, incoming)
            }

            if (matchIndex < 0) {
                result += incoming
            } else {
                result[matchIndex] = mergePair(result[matchIndex], incoming)
            }
        }

        return result.sortedWith(
            compareByDescending<VodItem> { it.playable }
                .thenByDescending { it.subtitles.any { sub -> sub.language.startsWith("pt") } }
                .thenBy { it.title.lowercase() }
        )
    }

    fun identityKey(item: VodItem): String {
        val title = normalizeTitle(item.title)
        val year = item.year?.take(4).orEmpty()
        return if (year.isBlank()) title else "$title|$year"
    }

    internal fun sameMovie(a: VodItem, b: VodItem): Boolean {
        val titleA = normalizeTitle(a.title)
        val titleB = normalizeTitle(b.title)
        if (titleA == titleB) {
            val yearA = a.year?.take(4)?.toIntOrNull()
            val yearB = b.year?.take(4)?.toIntOrNull()
            return yearA == null || yearB == null || abs(yearA - yearB) <= 1
        }

        if (titleA.length < 6 || titleB.length < 6) return false
        val tokensA = titleA.split(' ').filter { it.length > 2 }.toSet()
        val tokensB = titleB.split(' ').filter { it.length > 2 }.toSet()
        if (tokensA.isEmpty() || tokensB.isEmpty()) return false
        val intersection = tokensA.intersect(tokensB).size.toDouble()
        val union = tokensA.union(tokensB).size.toDouble()
        val similarity = if (union == 0.0) 0.0 else intersection / union
        if (similarity < 0.88) return false

        val yearA = a.year?.take(4)?.toIntOrNull()
        val yearB = b.year?.take(4)?.toIntOrNull()
        return yearA == null || yearB == null || abs(yearA - yearB) <= 1
    }

    private fun mergePair(a: VodItem, b: VodItem): VodItem {
        val primary = choosePrimary(a, b)
        val secondary = if (primary === a) b else a

        val allPlayback = buildList {
            primary.playbackUrl?.let(::add)
            secondary.playbackUrl?.let(::add)
            addAll(primary.alternatePlaybackUrls)
            addAll(secondary.alternatePlaybackUrls)
        }.filter(String::isNotBlank).distinct()

        return primary.copy(
            overview = primary.overview.ifBlank { secondary.overview },
            posterUrl = primary.posterUrl ?: secondary.posterUrl,
            backdropUrl = primary.backdropUrl ?: secondary.backdropUrl,
            year = primary.year ?: secondary.year,
            genres = (primary.genres + secondary.genres).distinct().take(12),
            language = primary.language.takeUnless { it == "und" } ?: secondary.language,
            playbackUrl = allPlayback.firstOrNull(),
            licenseName = primary.licenseName ?: secondary.licenseName,
            licenseUrl = primary.licenseUrl ?: secondary.licenseUrl,
            attribution = primary.attribution ?: secondary.attribution,
            subtitles = VodSubtitleSupport.preferPortuguese(
                primary.subtitles + secondary.subtitles
            ),
            rightsStatus = strongerRights(primary.rightsStatus, secondary.rightsStatus),
            providers = (primary.providers + secondary.providers + primary.source + secondary.source)
                .filter(String::isNotBlank)
                .distinct(),
            alternatePlaybackUrls = allPlayback.drop(1),
            externalIds = primary.externalIds + secondary.externalIds,
            durationSeconds = primary.durationSeconds ?: secondary.durationSeconds
        )
    }

    private fun choosePrimary(a: VodItem, b: VodItem): VodItem =
        listOf(a, b).maxByOrNull { item ->
            var score = 0
            if (item.playable) score += 100
            if (item.subtitles.any { it.language == "pt-BR" }) score += 30
            if (item.posterUrl != null) score += 10
            if (item.overview.isNotBlank()) score += 5
            score += when (item.rightsStatus) {
                RightsStatus.PUBLIC_DOMAIN -> 20
                RightsStatus.OPEN_LICENSE -> 18
                RightsStatus.ATTRIBUTION_REQUIRED -> 16
                RightsStatus.UNKNOWN -> 0
                RightsStatus.RESTRICTED -> -100
            }
            score
        } ?: a

    private fun strongerRights(a: RightsStatus, b: RightsStatus): RightsStatus {
        val rank = mapOf(
            RightsStatus.PUBLIC_DOMAIN to 5,
            RightsStatus.OPEN_LICENSE to 4,
            RightsStatus.ATTRIBUTION_REQUIRED to 3,
            RightsStatus.UNKNOWN to 2,
            RightsStatus.RESTRICTED to 1
        )
        return if ((rank[a] ?: 0) >= (rank[b] ?: 0)) a else b
    }

    internal fun normalizeTitle(value: String): String =
        Normalizer.normalize(value, Normalizer.Form.NFD)
            .replace(Regex("\\p{M}+"), "")
            .uppercase()
            .replace(Regex("[^A-Z0-9]+"), " ")
            .replace(Regex("\\b(THE|A|AN|O|A|OS|AS|UM|UMA|DE|DA|DO|DAS|DOS)\\b"), " ")
            .replace(Regex("\\s+"), " ")
            .trim()
}

package com.mukasanches.zapptv.vod

import android.content.ContentValues
import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteOpenHelper
import org.json.JSONArray
import org.json.JSONObject

data class CinemaIndexStats(
    val indexed: Int = 0,
    val playable: Int = 0,
    val portugueseSubtitles: Int = 0
)

class CinemaIndexStore(context: Context) :
    SQLiteOpenHelper(context.applicationContext, DB_NAME, null, DB_VERSION) {

    override fun onCreate(db: SQLiteDatabase) {
        db.execSQL(
            """
            CREATE TABLE $TABLE_MOVIES (
                identity_key TEXT PRIMARY KEY NOT NULL,
                item_json TEXT NOT NULL,
                search_text TEXT NOT NULL,
                playable INTEGER NOT NULL DEFAULT 0,
                has_pt_sub INTEGER NOT NULL DEFAULT 0,
                updated_at INTEGER NOT NULL
            )
            """.trimIndent()
        )
        db.execSQL("CREATE INDEX idx_movie_updated ON $TABLE_MOVIES(updated_at DESC)")
        db.execSQL("CREATE INDEX idx_movie_playable ON $TABLE_MOVIES(playable, updated_at DESC)")
        db.execSQL(
            """
            CREATE VIRTUAL TABLE $TABLE_SEARCH USING fts4(
                identity_key,
                search_text
            )
            """.trimIndent()
        )
    }

    override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) {
        if (oldVersion < 2) {
            db.execSQL("DROP TABLE IF EXISTS $TABLE_SEARCH")
            db.execSQL(
                """
                CREATE VIRTUAL TABLE $TABLE_SEARCH USING fts4(
                    identity_key,
                    search_text
                )
                """.trimIndent()
            )
            db.execSQL(
                """
                INSERT INTO $TABLE_SEARCH(identity_key, search_text)
                SELECT identity_key, search_text FROM $TABLE_MOVIES
                """.trimIndent()
            )
        }
    }

    fun upsert(items: List<VodItem>) {
        if (items.isEmpty()) return
        val now = System.currentTimeMillis()
        writableDatabase.beginTransaction()
        try {
            items.forEach { item ->
                val normalized = CinemaRightsEngine.normalize(item)
                val key = MovieIdentityResolver.identityKey(normalized)
                if (key.isBlank()) return@forEach

                val existing = readByKey(writableDatabase, key)
                val enriched = if (existing == null) {
                    normalized
                } else {
                    MovieIdentityResolver.merge(listOf(existing, normalized))
                        .firstOrNull() ?: normalized
                }
                val text = searchText(enriched)

                val values = ContentValues().apply {
                    put("identity_key", key)
                    put("item_json", toJson(enriched).toString())
                    put("search_text", text)
                    put(
                        "playable",
                        if (enriched.playable && CinemaRightsEngine.canAutoPlay(enriched)) 1 else 0
                    )
                    put(
                        "has_pt_sub",
                        if (enriched.subtitles.any { it.language.startsWith("pt") }) 1 else 0
                    )
                    put("updated_at", now)
                }
                writableDatabase.insertWithOnConflict(
                    TABLE_MOVIES,
                    null,
                    values,
                    SQLiteDatabase.CONFLICT_REPLACE
                )

                writableDatabase.delete(
                    TABLE_SEARCH,
                    "identity_key = ?",
                    arrayOf(key)
                )
                writableDatabase.insert(
                    TABLE_SEARCH,
                    null,
                    ContentValues().apply {
                        put("identity_key", key)
                        put("search_text", text)
                    }
                )
            }
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
        }
    }

    fun search(query: String, limit: Int = 250): List<VodItem> {
        val q = query.trim()
        if (q.isBlank()) return recent(limit)

        val safeLimit = limit.coerceIn(1, 1000)
        val match = ftsQuery(q)
        if (match.isNotBlank()) {
            val fts = runCatching {
                readableDatabase.rawQuery(
                    """
                    SELECT m.item_json
                    FROM $TABLE_SEARCH s
                    JOIN $TABLE_MOVIES m ON m.identity_key = s.identity_key
                    WHERE s.search_text MATCH ?
                    ORDER BY m.playable DESC, m.has_pt_sub DESC, m.updated_at DESC
                    LIMIT ?
                    """.trimIndent(),
                    arrayOf(match, safeLimit.toString())
                ).use { cursor ->
                    buildList {
                        while (cursor.moveToNext()) {
                            fromJson(cursor.getString(0))?.let(::add)
                        }
                    }
                }
            }.getOrDefault(emptyList())

            if (fts.isNotEmpty()) return fts
        }

        val like = "%${escapeLike(normalizeSearch(q))}%"
        val cursor = readableDatabase.query(
            TABLE_MOVIES,
            arrayOf("item_json"),
            "search_text LIKE ? ESCAPE '\\'",
            arrayOf(like),
            null,
            null,
            "playable DESC, has_pt_sub DESC, updated_at DESC",
            safeLimit.toString()
        )

        return cursor.use {
            buildList {
                while (it.moveToNext()) {
                    fromJson(it.getString(0))?.let(::add)
                }
            }
        }
    }

    fun recent(limit: Int = 250): List<VodItem> {
        val cursor = readableDatabase.query(
            TABLE_MOVIES,
            arrayOf("item_json"),
            null,
            null,
            null,
            null,
            "updated_at DESC",
            limit.coerceIn(1, 1000).toString()
        )

        return cursor.use {
            buildList {
                while (it.moveToNext()) {
                    fromJson(it.getString(0))?.let(::add)
                }
            }
        }
    }

    fun stats(): CinemaIndexStats {
        val cursor = readableDatabase.rawQuery(
            """
            SELECT
                COUNT(*),
                SUM(CASE WHEN playable = 1 THEN 1 ELSE 0 END),
                SUM(CASE WHEN has_pt_sub = 1 THEN 1 ELSE 0 END)
            FROM $TABLE_MOVIES
            """.trimIndent(),
            null
        )
        return cursor.use {
            if (!it.moveToFirst()) return@use CinemaIndexStats()
            CinemaIndexStats(
                indexed = it.getInt(0),
                playable = if (it.isNull(1)) 0 else it.getInt(1),
                portugueseSubtitles = if (it.isNull(2)) 0 else it.getInt(2)
            )
        }
    }

    private fun readByKey(db: SQLiteDatabase, key: String): VodItem? =
        db.query(
            TABLE_MOVIES,
            arrayOf("item_json"),
            "identity_key = ?",
            arrayOf(key),
            null,
            null,
            null,
            "1"
        ).use { cursor ->
            if (!cursor.moveToFirst()) null else fromJson(cursor.getString(0))
        }

    private fun ftsQuery(value: String): String =
        normalizeSearch(value)
            .split(Regex("\\s+"))
            .filter { it.length >= 2 }
            .take(8)
            .joinToString(" AND ") { token ->
                token.replace(Regex("[^a-z0-9]"), "") + "*"
            }

    private fun searchText(item: VodItem): String =
        normalizeSearch(
            listOf(
                item.title,
                item.overview,
                item.year.orEmpty(),
                item.source,
                item.catalog,
                item.genres.joinToString(" "),
                item.providers.joinToString(" "),
                item.attribution.orEmpty()
            ).joinToString(" ")
        )

    private fun normalizeSearch(value: String): String =
        MovieIdentityResolver.normalizeTitle(value).lowercase()

    private fun escapeLike(value: String): String =
        value.replace("\\", "\\\\")
            .replace("%", "\\%")
            .replace("_", "\\_")

    private fun toJson(item: VodItem): JSONObject =
        JSONObject().apply {
            put("id", item.id)
            put("title", item.title)
            put("overview", item.overview)
            put("posterUrl", item.posterUrl)
            put("backdropUrl", item.backdropUrl)
            put("year", item.year)
            put("genres", JSONArray(item.genres))
            put("language", item.language)
            put("playbackUrl", item.playbackUrl)
            put("source", item.source)
            put("catalog", item.catalog)
            put("detailUrl", item.detailUrl)
            put("licenseName", item.licenseName)
            put("licenseUrl", item.licenseUrl)
            put("attribution", item.attribution)
            put("subtitleLookupKey", item.subtitleLookupKey)
            put("rightsStatus", item.rightsStatus.name)
            put("providers", JSONArray(item.providers))
            put("alternatePlaybackUrls", JSONArray(item.alternatePlaybackUrls))
            put("durationSeconds", item.durationSeconds)
            put("kind", item.kind.name)

            val ids = JSONObject()
            item.externalIds.forEach(ids::put)
            put("externalIds", ids)

            val subtitles = JSONArray()
            item.subtitles.forEach { subtitle ->
                subtitles.put(
                    JSONObject().apply {
                        put("uri", subtitle.uri)
                        put("language", subtitle.language)
                        put("label", subtitle.label)
                        put("mimeType", subtitle.mimeType)
                        put("isDefault", subtitle.isDefault)
                    }
                )
            }
            put("subtitles", subtitles)
        }

    private fun fromJson(value: String): VodItem? =
        runCatching {
            val json = JSONObject(value)
            val subtitlesJson = json.optJSONArray("subtitles") ?: JSONArray()
            val subtitles = buildList {
                for (i in 0 until subtitlesJson.length()) {
                    val sub = subtitlesJson.optJSONObject(i) ?: continue
                    add(
                        VodSubtitle(
                            uri = sub.optString("uri"),
                            language = sub.optString("language", "und"),
                            label = sub.optString("label", "Legenda"),
                            mimeType = sub.optString("mimeType"),
                            isDefault = sub.optBoolean("isDefault", false)
                        )
                    )
                }
            }

            val idsJson = json.optJSONObject("externalIds") ?: JSONObject()
            val ids = buildMap {
                idsJson.keys().forEach { key ->
                    put(key, idsJson.optString(key))
                }
            }

            VodItem(
                id = json.getString("id"),
                title = json.getString("title"),
                overview = json.optString("overview"),
                posterUrl = json.optString("posterUrl").takeIf(String::isNotBlank),
                backdropUrl = json.optString("backdropUrl").takeIf(String::isNotBlank),
                year = json.optString("year").takeIf(String::isNotBlank),
                genres = json.optJSONArray("genres").toStringList(),
                language = json.optString("language", "und"),
                playbackUrl = json.optString("playbackUrl").takeIf(String::isNotBlank),
                source = json.optString("source"),
                catalog = json.optString("catalog"),
                detailUrl = json.optString("detailUrl").takeIf(String::isNotBlank),
                licenseName = json.optString("licenseName").takeIf(String::isNotBlank),
                licenseUrl = json.optString("licenseUrl").takeIf(String::isNotBlank),
                attribution = json.optString("attribution").takeIf(String::isNotBlank),
                subtitleLookupKey = json.optString("subtitleLookupKey").takeIf(String::isNotBlank),
                subtitles = subtitles,
                rightsStatus = runCatching {
                    RightsStatus.valueOf(json.optString("rightsStatus"))
                }.getOrDefault(RightsStatus.UNKNOWN),
                providers = json.optJSONArray("providers").toStringList(),
                alternatePlaybackUrls = json.optJSONArray("alternatePlaybackUrls").toStringList(),
                externalIds = ids,
                durationSeconds = json.optLong("durationSeconds").takeIf { it > 0L },
                kind = runCatching {
                    VodItem.Kind.valueOf(json.optString("kind"))
                }.getOrDefault(VodItem.Kind.MOVIE)
            )
        }.getOrNull()

    private fun JSONArray?.toStringList(): List<String> {
        if (this == null) return emptyList()
        return buildList {
            for (i in 0 until length()) {
                optString(i).takeIf(String::isNotBlank)?.let(::add)
            }
        }
    }

    companion object {
        private const val DB_NAME = "sanchestv-cinema-index.db"
        private const val DB_VERSION = 2
        private const val TABLE_MOVIES = "movie_index"
        private const val TABLE_SEARCH = "movie_search"
    }
}

package com.mukasanches.zapptv.vod

import android.content.Context

data class CinemaProviderConfig(
    val europeanaKey: String = "",
    val dplaKey: String = ""
)

class CinemaProviderConfigStore(context: Context) {
    private val prefs = context.applicationContext
        .getSharedPreferences(PREFS, Context.MODE_PRIVATE)

    fun get(): CinemaProviderConfig =
        CinemaProviderConfig(
            europeanaKey = prefs.getString(KEY_EUROPEANA, "").orEmpty(),
            dplaKey = prefs.getString(KEY_DPLA, "").orEmpty()
        )

    fun saveEuropeanaKey(value: String) {
        prefs.edit()
            .putString(KEY_EUROPEANA, value.trim())
            .apply()
    }

    fun saveDplaKey(value: String) {
        prefs.edit()
            .putString(KEY_DPLA, value.trim())
            .apply()
    }

    companion object {
        private const val PREFS = "sanchestv-cinema-provider-config"
        private const val KEY_EUROPEANA = "europeana_key"
        private const val KEY_DPLA = "dpla_key"
    }
}

package com.mukasanches.zapptv.vod

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll
import kotlinx.coroutines.coroutineScope
import okhttp3.Cache
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.net.URLEncoder
import java.util.concurrent.TimeUnit

data class CinemaProviderStatus(
    val key: String,
    val name: String,
    val enabled: Boolean,
    val requiresKey: Boolean = false
)

class InfiniteCinemaEngine(context: Context) {
    private val appContext = context.applicationContext
    private val legacy = OpenMovieCatalogRepository(appContext)
    private val index = CinemaIndexStore(appContext)
    private val configStore = CinemaProviderConfigStore(appContext)
    private val client = OkHttpClient.Builder()
        .cache(Cache(File(appContext.cacheDir, "infinite-cinema-http"), 128L * 1024L * 1024L))
        .connectTimeout(7, TimeUnit.SECONDS)
        .readTimeout(18, TimeUnit.SECONDS)
        .callTimeout(35, TimeUnit.SECONDS)
        .retryOnConnectionFailure(true)
        .build()

    suspend fun loadPage(page: Int): VodCatalogState = coroutineScope {
        val safePage = page.coerceAtLeast(1)
        val providers = providers()
        val jobs = providers.filter { it.enabled }.map { provider ->
            async(Dispatchers.IO) {
                runCatching { provider.loadPage(safePage) }
                    .getOrDefault(emptyList())
            }
        }

        val remote = jobs.awaitAll().flatten()
        val merged = MovieIdentityResolver.merge(remote)
        index.upsert(merged)
        val stats = index.stats()

        VodCatalogState(
            featured = merged.take(30),
            movies = merged,
            page = safePage,
            canLoadMore = merged.isNotEmpty(),
            status = buildString {
                append(merged.size)
                append(" títulos nesta descoberta • ")
                append(stats.indexed)
                append(" indexados localmente")
            },
            indexedCount = stats.indexed,
            playableCount = stats.playable,
            portugueseSubtitleCount = stats.portugueseSubtitles,
            providerCount = providers.count { it.enabled }
        )
    }

    suspend fun discoverBackgroundPage(page: Int): Int = coroutineScope {
        val safePage = page.coerceAtLeast(1)
        val jobs = providers()
            .filter { it.enabled && it.key != "legacy" }
            .map { provider ->
                async(Dispatchers.IO) {
                    runCatching { provider.loadPage(safePage) }
                        .getOrDefault(emptyList())
                }
            }

        val merged = MovieIdentityResolver.merge(jobs.awaitAll().flatten())
        index.upsert(merged)
        merged.size
    }

    suspend fun search(query: String): VodCatalogState = coroutineScope {
        val q = query.trim()
        if (q.isBlank()) {
            val local = index.recent(300)
            val stats = index.stats()
            return@coroutineScope VodCatalogState(
                featured = local.take(30),
                movies = local,
                status = stats.indexed.toString() + " títulos no índice local",
                indexedCount = stats.indexed,
                playableCount = stats.playable,
                portugueseSubtitleCount = stats.portugueseSubtitles,
                providerCount = providers().count { it.enabled }
            )
        }

        val localJob = async(Dispatchers.IO) { index.search(q, 250) }
        val remoteJobs = providers().filter { it.enabled }.map { provider ->
            async(Dispatchers.IO) {
                runCatching { provider.search(q, 1) }
                    .getOrDefault(emptyList())
            }
        }

        val combined = localJob.await() + remoteJobs.awaitAll().flatten()
        val merged = MovieIdentityResolver.merge(combined)
        index.upsert(merged)
        val stats = index.stats()

        VodCatalogState(
            featured = merged.take(30),
            movies = merged,
            canLoadMore = false,
            status = merged.size.toString() + " resultados federados • " +
                stats.indexed + " indexados",
            indexedCount = stats.indexed,
            playableCount = stats.playable,
            portugueseSubtitleCount = stats.portugueseSubtitles,
            providerCount = providers().count { it.enabled }
        )
    }

    suspend fun resolve(item: VodItem): VodItem {
        val resolved = when {
            item.id.startsWith("ia-deep:") -> archiveResolve(item)
            item.id.startsWith("nasa:") -> nasaResolve(item)
            item.id.startsWith("loc-global:") -> locResolve(item)
            item.id.startsWith("eu:") -> item
            item.id.startsWith("dpla:") -> item
            else -> legacy.resolve(item)
        }
        val normalized = CinemaRightsEngine.normalize(resolved)
        index.upsert(listOf(normalized))
        return normalized
    }

    fun localSearch(query: String): List<VodItem> =
        index.search(query, 300)

    fun stats(): CinemaIndexStats = index.stats()

    fun providerStatus(): List<CinemaProviderStatus> =
        providers().map {
            CinemaProviderStatus(
                key = it.key,
                name = it.name,
                enabled = it.enabled,
                requiresKey = it.requiresKey
            )
        }

    fun providerConfig(): CinemaProviderConfig = configStore.get()

    fun saveEuropeanaKey(value: String) = configStore.saveEuropeanaKey(value)

    fun saveDplaKey(value: String) = configStore.saveDplaKey(value)

    private fun providers(): List<CinemaProvider> {
        val config = configStore.get()
        return listOf(
            LegacyCinemaProvider(legacy),
            InternetArchiveDeepProvider(client),
            LibraryOfCongressGlobalProvider(client),
            NasaVideoProvider(client),
            EuropeanaProvider(client, config.europeanaKey),
            DplaProvider(client, config.dplaKey)
        )
    }

    private fun archiveResolve(item: VodItem): VodItem {
        val identifier = item.id.removePrefix("ia-deep:")
        val root = getJson(
            client,
            "https://archive.org/metadata/" + encodePath(identifier)
        ) ?: return item
        val metadata = root.optJSONObject("metadata")
        val rights = metadata?.optString("rights").orEmpty()
        val licenseUrl = metadata?.optString("licenseurl").orEmpty()

        if (!ArchiveRightsPolicy.isOpen(rights, licenseUrl)) {
            return item.copy(
                playbackUrl = null,
                rightsStatus = RightsStatus.UNKNOWN,
                licenseName = rights.takeIf(String::isNotBlank) ?: item.licenseName,
                licenseUrl = licenseUrl.takeIf(String::isNotBlank) ?: item.licenseUrl
            )
        }

        val videos = mutableListOf<Pair<Int, String>>()
        val subtitles = mutableListOf<VodSubtitle>()
        val files = root.optJSONArray("files") ?: JSONArray()
        for (i in 0 until files.length()) {
            val file = files.optJSONObject(i) ?: continue
            val name = file.optString("name")
            if (name.isBlank()) continue
            val url = "https://archive.org/download/" +
                encodePath(identifier) + "/" + encodePath(name)
            VodSubtitleSupport.fromUrl(url)?.let {
                subtitles += it
                continue
            }
            val score = videoScore(name, file.optString("format"))
            if (score > 0) videos += score to url
        }

        return item.copy(
            playbackUrl = videos.maxByOrNull { it.first }?.second,
            subtitles = VodSubtitleSupport.preferPortuguese(
                item.subtitles + subtitles
            ),
            licenseName = rights.takeIf(String::isNotBlank) ?: item.licenseName,
            licenseUrl = licenseUrl.takeIf(String::isNotBlank) ?: item.licenseUrl,
            rightsStatus = CinemaRightsEngine.classify(
                "Internet Archive",
                rights,
                licenseUrl
            )
        )
    }

    private fun nasaResolve(item: VodItem): VodItem {
        val nasaId = item.externalIds["nasa_id"]
            ?: item.id.removePrefix("nasa:")
        val root = getJson(
            client,
            "https://images-api.nasa.gov/asset/" + encodePath(nasaId)
        ) ?: return item
        val assets = root.optJSONObject("collection")
            ?.optJSONArray("items") ?: JSONArray()

        val videos = mutableListOf<Pair<Int, String>>()
        val subtitles = mutableListOf<VodSubtitle>()
        for (i in 0 until assets.length()) {
            val href = assets.optJSONObject(i)?.optString("href").orEmpty()
            if (!href.startsWith("https://")) continue
            VodSubtitleSupport.fromUrl(href)?.let {
                subtitles += it
                continue
            }
            val score = videoScore(href, "")
            if (score > 0) videos += score to href
        }

        return item.copy(
            playbackUrl = videos.maxByOrNull { it.first }?.second,
            subtitles = VodSubtitleSupport.preferPortuguese(
                item.subtitles + subtitles
            ),
            rightsStatus = RightsStatus.OPEN_LICENSE
        )
    }

    private fun locResolve(item: VodItem): VodItem {
        val detail = item.detailUrl ?: return item
        val separator = if ('?' in detail) "&" else "?"
        val root = getJson(client, detail + separator + "fo=json") ?: return item
        val direct = firstMediaUrl(root)

        val urls = mutableListOf<String>()
        collectUrls(root, urls)
        val subtitles = urls
            .mapNotNull(VodSubtitleSupport::fromUrl)

        return item.copy(
            playbackUrl = direct ?: item.playbackUrl,
            subtitles = VodSubtitleSupport.preferPortuguese(
                item.subtitles + subtitles
            )
        )
    }
}

