private class InternetArchiveDeepProvider(
    private val client: OkHttpClient
) : CinemaProvider {
    override val key = "archive-deep"
    override val name = "Internet Archive • Deep Discovery"
    override val enabled = true

    override suspend fun loadPage(page: Int): List<VodItem> {
        val slice = SLICES[(page - 1).mod(SLICES.size)]
        val innerPage = ((page - 1) / SLICES.size) + 1
        return queryArchive(slice, innerPage)
    }

    override suspend fun search(query: String, page: Int): List<VodItem> {
        val safe = query.replace("\"", " ").trim()
        if (safe.length < 2) return emptyList()
        val archiveQuery =
            "mediatype:movies AND (title:(\"$safe\") OR description:(\"$safe\"))"
        return queryArchive(archiveQuery, page)
            .filter { item ->
                ArchiveRightsPolicy.isOpen(item.licenseName, item.licenseUrl)
            }
    }

    private fun queryArchive(query: String, page: Int): List<VodItem> {
        val url = "https://archive.org/advancedsearch.php?q=" + encode(query) +
            "&fl%5B%5D=identifier&fl%5B%5D=title&fl%5B%5D=description" +
            "&fl%5B%5D=year&fl%5B%5D=date&fl%5B%5D=creator" +
            "&fl%5B%5D=subject&fl%5B%5D=licenseurl&fl%5B%5D=rights" +
            "&fl%5B%5D=downloads&sort%5B%5D=downloads%20desc" +
            "&rows=40&page=" + page.coerceAtLeast(1) + "&output=json"

        val docs = getJson(client, url)
            ?.optJSONObject("response")
            ?.optJSONArray("docs") ?: return emptyList()

        return buildList {
            for (i in 0 until docs.length()) {
                val doc = docs.optJSONObject(i) ?: continue
                val id = doc.optString("identifier").trim()
                val title = doc.optString("title").trim()
                if (id.isBlank() || title.isBlank()) continue
                val rights = jsonText(doc.opt("rights"))
                val licenseUrl = jsonText(doc.opt("licenseurl"))
                if (!ArchiveRightsPolicy.isOpen(rights, licenseUrl)) continue

                add(
                    VodItem(
                        id = "ia-deep:$id",
                        title = CinemaMetadataNormalizer.text(title),
                        overview = CinemaMetadataNormalizer.text(
                            jsonText(doc.opt("description"))
                        ),
                        posterUrl = "https://archive.org/services/img/" + encodePath(id),
                        year = CinemaMetadataNormalizer.year(
                            jsonText(doc.opt("year")).ifBlank {
                                jsonText(doc.opt("date"))
                            }
                        ),
                        genres = jsonStrings(doc.opt("subject")).take(12),
                        source = "Internet Archive",
                        catalog = "Internet Archive • Deep Discovery",
                        detailUrl = "https://archive.org/details/" + encodePath(id),
                        licenseName = rights.takeIf(String::isNotBlank),
                        licenseUrl = licenseUrl.takeIf(String::isNotBlank),
                        attribution = jsonText(doc.opt("creator"))
                            .takeIf(String::isNotBlank),
                        rightsStatus = CinemaRightsEngine.classify(
                            "Internet Archive",
                            rights,
                            licenseUrl
                        ),
                        providers = listOf("Internet Archive"),
                        externalIds = mapOf("archive_identifier" to id)
                    )
                )
            }
        }
    }

    companion object {
        private val SLICES = listOf(
            "mediatype:movies AND rights:\"Public Domain\" AND date:[1890-01-01 TO 1919-12-31]",
            "mediatype:movies AND rights:\"Public Domain\" AND date:[1920-01-01 TO 1939-12-31]",
            "mediatype:movies AND rights:\"Public Domain\" AND date:[1940-01-01 TO 1959-12-31]",
            "mediatype:movies AND rights:\"Public Domain\" AND date:[1960-01-01 TO 1979-12-31]",
            "mediatype:movies AND licenseurl:*creativecommons.org* AND date:[1980-01-01 TO 1999-12-31]",
            "mediatype:movies AND licenseurl:*creativecommons.org* AND date:[2000-01-01 TO 2009-12-31]",
            "mediatype:movies AND licenseurl:*creativecommons.org* AND date:[2010-01-01 TO 2019-12-31]",
            "mediatype:movies AND licenseurl:*creativecommons.org* AND date:[2020-01-01 TO 2029-12-31]",
            "collection:opensource_movies AND mediatype:movies",
            "collection:prelinger AND mediatype:movies"
        )
    }
}

private class LibraryOfCongressGlobalProvider(
    private val client: OkHttpClient
) : CinemaProvider {
    override val key = "loc-global"
    override val name = "Library of Congress • Film & Videos"
    override val enabled = true

    override suspend fun loadPage(page: Int): List<VodItem> =
        fetch(
            "https://www.loc.gov/film-and-videos/?fo=json&c=50&sp=" +
                page.coerceAtLeast(1)
        )

    override suspend fun search(query: String, page: Int): List<VodItem> =
        fetch(
            "https://www.loc.gov/film-and-videos/?fo=json&c=50&sp=" +
                page.coerceAtLeast(1) + "&q=" + encode(query)
        )

    private fun fetch(url: String): List<VodItem> {
        val results = getJson(client, url)?.optJSONArray("results")
            ?: return emptyList()

        return buildList {
            for (i in 0 until results.length()) {
                val result = results.optJSONObject(i) ?: continue
                val title = CinemaMetadataNormalizer.text(result.optString("title"))
                val detail = result.optString("id")
                    .ifBlank { result.optString("url") }
                if (title.isBlank() || detail.isBlank()) continue
                val rights = jsonText(result.opt("rights"))

                val rightsStatus = CinemaRightsEngine.classify(
                    "Library of Congress",
                    rights,
                    null
                )
                val direct = firstMediaUrl(result).takeIf {
                    rightsStatus in setOf(
                        RightsStatus.PUBLIC_DOMAIN,
                        RightsStatus.OPEN_LICENSE,
                        RightsStatus.ATTRIBUTION_REQUIRED
                    )
                }

                add(
                    VodItem(
                        id = "loc-global:" + detail.hashCode(),
                        title = title,
                        overview = CinemaMetadataNormalizer.text(
                            jsonText(result.opt("description"))
                        ),
                        posterUrl = result.optJSONArray("image")
                            ?.optString(0)?.takeIf(String::isNotBlank),
                        year = CinemaMetadataNormalizer.year(
                            jsonText(result.opt("date"))
                        ),
                        playbackUrl = direct,
                        source = "Library of Congress",
                        catalog = "LOC • Film & Videos",
                        detailUrl = detail,
                        licenseName = rights.takeIf(String::isNotBlank)
                            ?: "Rights advisory in Library of Congress record",
                        attribution = "Library of Congress",
                        rightsStatus = rightsStatus,
                        providers = listOf("Library of Congress"),
                        externalIds = mapOf("loc" to detail)
                    )
                )
            }
        }
    }
}

private class NasaVideoProvider(
    private val client: OkHttpClient
) : CinemaProvider {
    override val key = "nasa"
    override val name = "NASA Image and Video Library"
    override val enabled = true

    override suspend fun loadPage(page: Int): List<VodItem> =
        fetch(
            "https://images-api.nasa.gov/search?media_type=video&page=" +
                page.coerceAtLeast(1)
        )

    override suspend fun search(query: String, page: Int): List<VodItem> =
        fetch(
            "https://images-api.nasa.gov/search?media_type=video&page=" +
                page.coerceAtLeast(1) + "&q=" + encode(query)
        )

    private fun fetch(url: String): List<VodItem> {
        val items = getJson(client, url)
            ?.optJSONObject("collection")
            ?.optJSONArray("items") ?: return emptyList()

        return buildList {
            for (i in 0 until items.length()) {
                val raw = items.optJSONObject(i) ?: continue
                val data = raw.optJSONArray("data")?.optJSONObject(0) ?: continue
                val nasaId = data.optString("nasa_id").trim()
                val title = CinemaMetadataNormalizer.text(data.optString("title"))
                if (nasaId.isBlank() || title.isBlank()) continue
                val preview = raw.optJSONArray("links")
                    ?.optJSONObject(0)
                    ?.optString("href")
                    ?.takeIf(String::isNotBlank)

                add(
                    VodItem(
                        id = "nasa:$nasaId",
                        title = title,
                        overview = CinemaMetadataNormalizer.text(
                            data.optString("description")
                        ),
                        posterUrl = preview,
                        year = CinemaMetadataNormalizer.year(
                            data.optString("date_created")
                        ),
                        genres = jsonStrings(data.opt("keywords")).take(12),
                        source = "NASA Image and Video Library",
                        catalog = "NASA • Vídeos e documentários",
                        detailUrl = "https://images.nasa.gov/details/" + encodePath(nasaId),
                        licenseName = "NASA Media Usage Guidelines",
                        licenseUrl = "https://www.nasa.gov/nasa-brand-center/images-and-media/",
                        attribution = data.optString("center").takeIf(String::isNotBlank)
                            ?: "NASA",
                        rightsStatus = RightsStatus.OPEN_LICENSE,
                        providers = listOf("NASA"),
                        externalIds = mapOf("nasa_id" to nasaId)
                    )
                )
            }
        }
    }
}

private class EuropeanaProvider(
    private val client: OkHttpClient,
    private val apiKey: String
) : CinemaProvider {
    override val key = "europeana"
    override val name = "Europeana • Open Video"
    override val enabled = apiKey.isNotBlank()
    override val requiresKey = true

    override suspend fun loadPage(page: Int): List<VodItem> =
        fetch("*", page)

    override suspend fun search(query: String, page: Int): List<VodItem> =
        fetch(query, page)

    private fun fetch(query: String, page: Int): List<VodItem> {
        if (!enabled) return emptyList()
        val start = ((page.coerceAtLeast(1) - 1) * 40) + 1
        val url = "https://api.europeana.eu/record/v2/search.json?wskey=" +
            encode(apiKey) +
            "&query=" + encode(query) +
            "&qf=TYPE%3AVIDEO&qf=REUSABILITY%3Aopen" +
            "&media=true&profile=rich&rows=40&start=" + start

        val items = getJson(client, url)?.optJSONArray("items")
            ?: return emptyList()

        return buildList {
            for (i in 0 until items.length()) {
                val raw = items.optJSONObject(i) ?: continue
                val id = raw.optString("id").trim()
                val title = firstString(raw.opt("title"))
                if (id.isBlank() || title.isBlank()) continue
                val rights = firstString(raw.opt("rights"))
                val direct = firstString(raw.opt("edmIsShownBy"))
                    .takeIf(::looksLikeVideoUrl)

                add(
                    VodItem(
                        id = "eu:" + id.hashCode(),
                        title = CinemaMetadataNormalizer.text(title),
                        overview = CinemaMetadataNormalizer.text(
                            firstString(raw.opt("dcDescription"))
                        ),
                        posterUrl = firstString(raw.opt("edmPreview"))
                            .takeIf(String::isNotBlank),
                        year = CinemaMetadataNormalizer.year(
                            firstString(raw.opt("year"))
                        ),
                        playbackUrl = direct,
                        source = "Europeana",
                        catalog = "Europeana • Open Video",
                        detailUrl = firstString(raw.opt("guid"))
                            .takeIf(String::isNotBlank),
                        licenseName = rights.takeIf(String::isNotBlank)
                            ?: "Europeana reusability=open",
                        licenseUrl = rights.takeIf { it.startsWith("http") },
                        rightsStatus = RightsStatus.OPEN_LICENSE,
                        providers = listOf("Europeana"),
                        externalIds = mapOf("europeana" to id)
                    )
                )
            }
        }
    }
}

private class DplaProvider(
    private val client: OkHttpClient,
    private val apiKey: String
) : CinemaProvider {
    override val key = "dpla"
    override val name = "DPLA • Moving Image"
    override val enabled = apiKey.isNotBlank()
    override val requiresKey = true

    override suspend fun loadPage(page: Int): List<VodItem> =
        fetch("", page)

    override suspend fun search(query: String, page: Int): List<VodItem> =
        fetch(query, page)

    private fun fetch(query: String, page: Int): List<VodItem> {
        if (!enabled) return emptyList()
        val base = StringBuilder(
            "https://api.dp.la/v2/items?sourceResource.type=Moving%20Image" +
                "&page_size=40&page=" + page.coerceAtLeast(1) +
                "&api_key=" + encode(apiKey)
        )
        if (query.isNotBlank()) {
            base.append("&q=").append(encode(query))
        }

        val docs = getJson(client, base.toString())?.optJSONArray("docs")
            ?: return emptyList()

        return buildList {
            for (i in 0 until docs.length()) {
                val raw = docs.optJSONObject(i) ?: continue
                val id = raw.optString("id")
                val source = raw.optJSONObject("sourceResource")
                val title = firstString(source?.opt("title"))
                if (id.isBlank() || title.isBlank()) continue
                val rights = firstString(source?.opt("rights"))
                val shownAt = firstString(raw.opt("isShownAt"))

                add(
                    VodItem(
                        id = "dpla:$id",
                        title = CinemaMetadataNormalizer.text(title),
                        overview = CinemaMetadataNormalizer.text(
                            firstString(source?.opt("description"))
                        ),
                        posterUrl = firstString(raw.opt("object"))
                            .takeIf(String::isNotBlank),
                        year = CinemaMetadataNormalizer.year(
                            firstString(source?.opt("date"))
                        ),
                        source = "DPLA",
                        catalog = "DPLA • Moving Image",
                        detailUrl = shownAt.takeIf(String::isNotBlank),
                        licenseName = rights.takeIf(String::isNotBlank),
                        rightsStatus = CinemaRightsEngine.classify(
                            "DPLA",
                            rights,
                            null
                        ),
                        providers = listOf("DPLA"),
                        externalIds = mapOf("dpla" to id)
                    )
                )
            }
        }
    }
}

object CinemaMetadataNormalizer {
    fun text(value: String): String =
        value.replace(Regex("<[^>]+>"), " ")
            .replace("&amp;", "&")
            .replace("&quot;", "\"")
            .replace("&#39;", "'")
            .replace(Regex("\\s+"), " ")
            .trim()

    fun year(value: String): String? =
        Regex("""\b(18|19|20)\d{2}\b""")
            .find(value)
            ?.value
}

private fun getJson(client: OkHttpClient, url: String): JSONObject? {
    val request = Request.Builder()
        .url(url)
        .header("Accept", "application/json")
        .header("User-Agent", "SANCHESTV/2.9 AndroidTV InfiniteCinema")
        .build()

    return runCatching {
        client.newCall(request).execute().use { response ->
            if (!response.isSuccessful) return@use null
            JSONObject(response.body.string())
        }
    }.getOrNull()
}

private fun firstMediaUrl(value: Any?): String? {
    val urls = mutableListOf<String>()
    collectUrls(value, urls)
    return urls.filter(::looksLikeVideoUrl)
        .sortedByDescending(::videoUrlScore)
        .firstOrNull()
}

private fun collectUrls(value: Any?, output: MutableList<String>) {
    when (value) {
        is JSONObject -> value.keys().forEach { collectUrls(value.opt(it), output) }
        is JSONArray -> for (i in 0 until value.length()) collectUrls(value.opt(i), output)
        is String -> if (value.startsWith("https://")) output += value
    }
}

private fun looksLikeVideoUrl(url: String): Boolean {
    val clean = url.substringBefore('?').lowercase()
    return clean.endsWith(".mp4") ||
        clean.endsWith(".m4v") ||
        clean.endsWith(".webm") ||
        clean.endsWith(".mov") ||
        clean.endsWith(".ogv") ||
        clean.endsWith(".m3u8") ||
        clean.endsWith(".mpd")
}

private fun videoUrlScore(url: String): Int {
    val lower = url.lowercase()
    return when {
        ".m3u8" in lower -> 130
        ".mpd" in lower -> 125
        ".mp4" in lower && ("1080" in lower || "720" in lower) -> 120
        ".mp4" in lower -> 110
        ".webm" in lower -> 100
        ".m4v" in lower -> 90
        ".mov" in lower -> 80
        ".ogv" in lower -> 70
        else -> 0
    }
}

private fun videoScore(name: String, format: String): Int {
    val lower = name.substringBefore('?').lowercase()
    var score = videoUrlScore(lower)
    if (score == 0) return 0
    val fmt = format.lowercase()
    if ("h.264" in fmt || "mpeg4" in fmt) score += 20
    if ("sample" in lower || "trailer" in lower || "preview" in lower) score -= 80
    return score
}

private fun jsonText(value: Any?): String = when (value) {
    is JSONArray -> buildList {
        for (i in 0 until value.length()) {
            value.optString(i).takeIf(String::isNotBlank)?.let(::add)
        }
    }.joinToString(" • ")
    is String -> value
    is Number -> value.toString()
    else -> ""
}

private fun jsonStrings(value: Any?): List<String> = when (value) {
    is JSONArray -> buildList {
        for (i in 0 until value.length()) {
            value.optString(i).takeIf(String::isNotBlank)?.let(::add)
        }
    }
    is String -> listOf(value)
    else -> emptyList()
}

private fun firstString(value: Any?): String = when (value) {
    is JSONArray -> value.optString(0)
    is String -> value
    else -> ""
}

private fun encode(value: String): String =
    URLEncoder.encode(value, "UTF-8").replace("+", "%20")

private fun encodePath(value: String): String =
    URLEncoder.encode(value, "UTF-8")
        .replace("+", "%20")
        .replace("%2F", "/")
